    @('AnOperationEndsWithoutAnEffect', 'PROPERTIES', $ex, 1, 0, 0, 0,
      'an operation ends having found nothing to change'),
    @('AnInnerOperationRuns', 'PROPERTIES', $ex, 1, 0, 0, 0,
