    @('AConversionIsCancelled', 'PROPERTIES', $safeR, 0, 0, 0, 0,
      'a conversion is cancelled after its drain and leaves the handle detached'),
    @('AConversionFailsAtTheRecheck', 'PROPERTIES', $twoSafe, 0, 0, 0, 0,
