    @('AnUpgraderDiesWhileDraining', 'PROPERTIES', $safeR, 0, 1, 0, 0,
      'an upgrader dies while its handle drains', 1),
    @('ADeathEndsTheLeases', 'PROPERTIES', $safeR, 0, 1, 0, 0,
      'a process dies with operations of its clones in flight, which ends them', 1),
    @('AHandleRegisters', 'PROPERTIES', $ex, 0, 0, 0, 0,
      'a handle writes its entry and its attach returns', 0, 1, 0),
    @('AHandleAttachesUnregistered', 'PROPERTIES', $ex, 0, 0, 0, 0,
      'a handle finds every entry held and attaches without one, which the registry records', 0, 1, 0),
    @('AnEntryOfADeadHandleIsReused', 'PROPERTIES', $ex, 0, 1, 0, 0,
      'a handle takes an entry that still carries the token of a handle that died', 0, 1, 0),
    @('ARegistrantMovesOnFromAHeldClaim', 'PROPERTIES', $ex, 0, 0, 0, 0,
      'a handle finds an entry claim lock held and moves on without waiting', 0, 1, 0),
    @('ARegistrantMovesOnFromALiveEntry', 'PROPERTIES', $ex, 0, 0, 0, 0,
      'a handle claims an entry, finds its liveness lock held, and moves on', 0, 1, 0),
    @('AnOwnerUpdatesItsEntry', 'PROPERTIES', $safeR, 0, 0, 0, 0,
