    @('ARecoveryFollowsARestartWithNothingHalfApplied', 'PROPERTIES', $ex, 1, 0, 1, 0, 'recovery of unlogged writes runs after a host crash that left nothing half applied', 0, 0, 0, $false, 0, 0, '', $true),
    @('ARecoveryFollowsAHoldersDeath', 'PROPERTIES', $ex, 2, 1, 0, 0, 'recovery of unlogged writes runs after a holder died between its effects, while another process was attached', 0, 0, 0, $false, 0, 0, 'Unlogged', $true),
    @('ARecoveryClearsTheFence', 'PROPERTIES', $ex, 1, 0, 0, 0, 'recovery clears the fence in its last step', 0, 0, 0, $true),
