    @('AResumerIsStoppedInTheUpgrade', 'PROPERTIES', $safeResume, 2, 1, 0, 0, 'a recoverer stops between the steps of an upgrade it resumes', 0, 0, 0, $true, 0, 2),
    @('AResumerDiesInTheUpgrade', 'INVARIANTS', $bStw, 3, 1, 0, 0, 'a recoverer dies between the steps of an upgrade it resumes and the next acquirer, which speaks the target schema, is told recovery is required', 0, 0, 0, $true, 0, 2),
    @('AReaderIsAdmittedDuringTheBody', 'PROPERTIES', $safeR, 1, 0, 0, 0, 'a handle that may only read is admitted while an upgrader is in its body', 0, 0, 0, $true, 0, 2),
    @('AnUpgradeCompletesAfterAFailedClosingPublication', 'PROPERTIES', $safeResume, 1, 0, 0, 0, 'an upgrade completes and the closing publication of the count fails, leaving the fence set', 0, 0, 0, $true, 0, 2),
    @('DiscoveryMeetsALiveUpgradersBody', 'PROPERTIES', $safeR, 0, 0, 0, 0, 'discovery runs while an upgrader is in its body and reports recovery as not required', 0, 0, 0, $true, 1, 2),
    @('DiscoveryFindsAnInterruptedUpgrade', 'PROPERTIES', $safeR, 0, 1, 0, 0, 'discovery reports recovery required because an upgrader died in its body, which a record under a free lock shows', 0, 0, 0, $true, 1, 2)
)
$witnesses += @(
    @('AReaderOfAnOlderSchemaSurvivesASafeUpgrade', 'PROPERTIES', $layered.ChainSafe, 0, 0, 0, 0, 'a reader that speaks an older schema than the current one stays attached while an upgrade that is safe for readers completes'),
    @('AReaderTwoSchemasBehindSurvivesASafeUpgrade', 'PROPERTIES', $layered.ChainSafe, 0, 0, 0, 0, 'a reader of the first source schema stays attached through two upgrades in a row that are safe for readers'),
    @('AnUpgradeIsUnsafeAgainstTheOldestAndSafeAgainstTheCurrent', 'PROPERTIES', $layered.ChainFloor, 0, 0, 0, 0, 'an upgrade is recorded as unsafe for readers although its floor is at or below the current schema, because the oldest schema the store admits is below the floor'),
    @('AnUpgradeOfOneLayerRunsBesideHandlesOfAnother', 'PROPERTIES', $layered.TwoLayersSafe, 0, 0, 0, 0, 'a handle that speaks an older schema of one layer is admitted while an upgrade of another layer is in progress'),
    @('TwoLayersAreUpgradedInTurn', 'PROPERTIES', $layered.TwoLayerUpgradesSafe, 0, 0, 0, 0, 'an upgrade of one layer completes after an upgrade of another layer has completed'),
    @('AnUnsafeUpgradeOfTheSecondLayerCompletes', 'PROPERTIES', $layered.TwoLayerUpgradesUnsafe, 0, 0, 0, 0, 'an upgrade of the second layer that is unsafe for readers completes and raises the oldest reader schema of that layer'),
    @('AWriterIsAdmittedBesideAnUpgradeOfAnotherLayer', 'PROPERTIES', $layered.TwoLayersSafe, 0, 1, 0, 0, 'a handle that may write, speaks the target of the layer whose upgrade its upgrader left interrupted and the current schema of the other layer, and is admitted'),
    @('AWriterIsAdmittedBesideAnUpgradeOfAnotherLayer', 'PROPERTIES', $layered.TwoLayersSafe, 0, 1, 0, 0, 'a handle that may write, speaks the target of the layer whose upgrade, with a body, its upgrader left interrupted and the current schema of the other layer, and is admitted', 0, 0, 0, $true, 0, 1, 'Body'),
    @('AReaderTwoSchemasBehindSurvivesASafeUpgrade', 'PROPERTIES', $layered.ChainSafe, 0, 0, 0, 0, 'a reader of the first source schema stays attached through two upgrades in a row, through their bodies, that are safe for readers', 0, 0, 0, $true, 0, 1, 'Body'),
    @('AnUpgradeIsUnsafeAgainstTheOldestAndSafeAgainstTheCurrent', 'PROPERTIES', $layered.ChainFloor, 0, 0, 0, 0, 'an upgrade with a body is recorded as unsafe for readers although its floor is at or below the current schema, because the oldest schema the store admits is below the floor', 0, 0, 0, $true, 0, 1, 'Body'),
    @('AnUpgradeOfOneLayerRunsBesideHandlesOfAnother', 'PROPERTIES', $layered.TwoLayersSafe, 0, 0, 0, 0, 'a handle that speaks an older schema of one layer is admitted while an upgrade with a body of another layer is in progress', 0, 0, 0, $true, 0, 1, 'Body'),
    @('TwoLayersAreUpgradedInTurn', 'PROPERTIES', $layered.TwoLayerUpgradesSafe, 0, 0, 0, 0, 'an upgrade of one layer through its body completes after an upgrade of another layer has completed', 0, 0, 0, $true, 0, 1, 'Body'),
    @('AnUnsafeUpgradeOfTheSecondLayerCompletes', 'PROPERTIES', $layered.TwoLayerUpgradesUnsafe, 0, 0, 0, 0, 'an upgrade of the second layer through its body that is unsafe for readers completes and raises the oldest reader schema of that layer', 0, 0, 0, $true, 0, 1, 'Body')
)
foreach ($w in $witnesses) {
    $name = "Witness_$($w[0])"
    $pair = One $w[1] $name
    $leases = if ($w.Count -gt 8) { $w[8] } else { 0 }
    $slots = if ($w.Count -gt 9) { $w[9] } else { 0 }
    $listings = if ($w.Count -gt 10) { $w[10] } else { 0 }
    $txn = if ($w.Count -gt 11) { $w[11] } else { $false }
    $discoveries = if ($w.Count -gt 12) { $w[12] } else { 0 }
    $upSteps = if ($w.Count -gt 13) { $w[13] } else { 0 }
    $suffix = if ($w.Count -gt 14) { $w[14] } else { '' }
    $unlogged = if ($w.Count -gt 15) { $w[15] } else { $false }
    $mixed = if ($w.Count -gt 16) { $w[16] } else { $false }
    $text = Cfg $w[2] $w[3] $w[4] $w[5] $w[6] 'none' $true $false $pair[0] $pair[1] $leases $slots $listings $txn $discoveries $upSteps $unlogged $mixed
    Write-Cfg "Coordination-Witness-$($w[0])$suffix.cfg" `
        (Header @("Witness: $($w[7]).", "TLC must report $name violated, which shows it is reachable.")) $text
}
